<?php require 'config.php';require 'includes/functions.php';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("SELECT * FROM users WHERE email=? AND active=1");$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];go('account.php');}flash('Incorrect email or password.','error');}$title='Sign in';require 'includes/header.php';?><div class="formbox"><span class="eyebrow">WELCOME BACK</span><h1>Sign in</h1><form method="post"><?=csrf_field()?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="button dark full">Sign in</button></form><p>New to StyleHub? <a href="register.php">Create an account</a></p></div><?php require 'includes/footer.php';?>